import{_ as o,o as a,c as e,a2 as l}from"./chunks/framework.CdvW4CUT.js";const h=JSON.parse('{"title":"关于","description":"","frontmatter":{},"headers":[],"relativePath":"about.md","filePath":"about.md"}'),r={name:"about.md"};function i(n,t,s,u,c,d){return a(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="关于" tabindex="-1">关于 <a class="header-anchor" href="#关于" aria-label="Permalink to &quot;关于&quot;">​</a></h1><p>我是一名 Agent 开发工程师，主要做执行链路、工具调用、审批与取消、任务调度这类&quot;跑起来之后才暴露问题&quot;的工程方向。</p><p>这个站点记录我在真实系统里遇到的问题：怎么定位、怎么验证、怎么修、以及哪些结论其实还没被证明。写下来的目的有两个——提醒自己别把&quot;看起来好了&quot;当成&quot;已经好了&quot;；也希望能给遇到同类问题的同行省一点时间。</p><h2 id="关注方向" tabindex="-1">关注方向 <a class="header-anchor" href="#关注方向" aria-label="Permalink to &quot;关注方向&quot;">​</a></h2><ul><li><strong>Agent 执行链路</strong>：任务/会话/尝试的状态推进，审批（HITL）与取消的最终一致性</li><li><strong>性能排查</strong>：常驻服务空闲态开销、数据库轮询与连接复用、采样与对照实验</li><li><strong>并发正确性</strong>：跨请求凭据一致性、幂等、出站队列与对账</li><li><strong>质量工程</strong>：真实数据库回归、CI 抖动归因、测试阈值该不该动</li><li><strong>跨平台工程</strong>：Windows/POSIX 在进程、路径、权限模型上的差异</li></ul><h2 id="写作原则" tabindex="-1">写作原则 <a class="header-anchor" href="#写作原则" aria-label="Permalink to &quot;写作原则&quot;">​</a></h2><ol><li>先证据，后结论；没有证据的判断标注为&quot;待验证&quot;</li><li>指标带口径：环境、采样窗口、统计对象、不能代表什么</li><li>未达标就写未达标；失败轮次与修正过程保留</li><li>全部内容脱敏，不涉及任何公司内部信息</li></ol><blockquote><p>本站为个人学习与实践记录，不代表任何雇主观点。</p></blockquote>',8)])])}const p=o(r,[["render",i]]);export{h as __pageData,p as default};
